using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace SlopStudio {
 public sealed partial class MainForm {
  private ContextMenuStrip _instrumentMenu;private GlobalTracksPanel _globalTracks;private readonly List<Tuple<Guid,TrackType,Region>> _regionClipboard=new List<Tuple<Guid,TrackType,Region>>();private bool _scaling;private Timer _scaleTimer;private VideoPreviewForm _videoWindow;
  private Func<Point> _editorPointer=()=>MousePosition;
  private bool PianoContext(){if(_pianoRoll==null||!_pianoRoll.Visible)return false;Point p=_editorPointer();if(_timeline!=null&&_timeline.RectangleToScreen(_timeline.ClientRectangle).Contains(p))return false;return _pianoRoll.RectangleToScreen(_pianoRoll.ClientRectangle).Contains(p)||_pianoRoll.ContainsFocus;}
  private void InitializeV8Features(){
   foreach(var command in new[]{AppCommand.JoinRegions,AppCommand.Copy,AppCommand.Cut,AppCommand.Paste,AppCommand.SelectAll,AppCommand.DeselectAll,AppCommand.InvertSelection})AddCommandMenu(_editMenu,command,UiText.CommandName(command));_globalTracks=new GlobalTracksPanel{Dock=DockStyle.Top,Height=8};_timeline.Controls.Add(_globalTracks);_globalTracks.BringToFront();_globalTracks.Project=()=>_project;_globalTracks.Header=()=>_timeline.HeaderWidth;_globalTracks.Zoom=()=>_timeline.Zoom;_globalTracks.First=()=>_timeline.HorizontalBeat;_globalTracks.EditRequested+=EditGlobalTracks;
   AddCommandMenu(_viewMenu,AppCommand.ShowGlobalTracks,"Global Tracks");AddCommandMenu(_viewMenu,AppCommand.ZoomVerticalOut,"Zoom Vertical Out");AddCommandMenu(_viewMenu,AppCommand.ZoomVerticalIn,"Zoom Vertical In");AddCommandMenu(_viewMenu,AppCommand.ZoomFitSelection,"Zoom to Selection");AddCommandMenu(_fileMenu,AppCommand.ImportVideo,"Import Video…");AddCommandMenu(_helpMenu,AppCommand.MitLicences,"MIT Licences");var monitor=new ToolStripMenuItem("MIDI Input Monitor");monitor.Click+=delegate{ShowMidiMonitor();};_viewMenu.DropDownItems.Add(monitor);var movie=new ToolStripMenuItem("Movie Preview");movie.Click+=delegate{ShowMovie();};_viewMenu.DropDownItems.Add(movie);var importReport=new ToolStripMenuItem("Import Report");importReport.Click+=delegate{MessageBox.Show(this,String.IsNullOrEmpty(_project.Studio.ImportNotes)?UiText.Translate("No import warnings."):_project.Studio.ImportNotes,UiText.Translate("Import report"));};_viewMenu.DropDownItems.Add(importReport);
   _scaleTimer=new Timer{Interval=32};_scaleTimer.Tick+=delegate{_scaleTimer.Stop();if(!IsDisposed)ApplyUiScale();};FormClosed+=delegate{_scaleTimer.Stop();_scaleTimer.Dispose();if(_videoWindow!=null&&!_videoWindow.IsDisposed)_videoWindow.Close();};
  }
  private bool ExecuteV8(AppCommand command){
   if(PianoContext()){if(command==AppCommand.ToolMenu){_pianoRoll.ShowTools();return true;}if(command==AppCommand.ZoomFitSelection){_pianoRoll.FitSelection();return true;}if(command==AppCommand.ZoomIn||command==AppCommand.ZoomOut){_pianoRoll.ZoomHorizontal(command==AppCommand.ZoomIn?1:-1);return true;}if(command==AppCommand.ZoomVerticalIn||command==AppCommand.ZoomVerticalOut){_pianoRoll.ZoomVertical(command==AppCommand.ZoomVerticalIn?1:-1);return true;}if(_pianoRoll.EditCommand(command,_cursorBeat))return true;}
   if(command==AppCommand.ZoomVerticalIn||command==AppCommand.ZoomVerticalOut){_timeline.ZoomVertical(command==AppCommand.ZoomVerticalIn?1:-1);return true;}
   if(command==AppCommand.TransposeUp||command==AppCommand.TransposeDown||command==AppCommand.TransposeOctaveUp||command==AppCommand.TransposeOctaveDown||command==AppCommand.NudgeLeft||command==AppCommand.NudgeRight||command==AppCommand.LengthLeft||command==AppCommand.LengthRight){var selected=new HashSet<Guid>(_timeline.SelectedRegions);if(selected.Count==0&&_selectedRegionId.HasValue)selected.Add(_selectedRegionId.Value);var changes=new List<IProjectCommand>();int pitch=command==AppCommand.TransposeUp?1:command==AppCommand.TransposeDown?-1:command==AppCommand.TransposeOctaveUp?12:command==AppCommand.TransposeOctaveDown?-12:0;foreach(var t in _project.Tracks)foreach(var r in t.Regions)if(selected.Contains(r.Id)){if(pitch!=0&&t.Type==TrackType.Midi)changes.Add(new SetRegionOptionsCommand(t,r,r.Muted,Math.Max(-48,Math.Min(48,r.Transpose+pitch)),r.VelocityOffset));else if(command==AppCommand.NudgeLeft||command==AppCommand.NudgeRight)changes.Add(new MoveRegionCommand(t.Id,r.Id,r.StartBeat,Math.Max(0,r.StartBeat+(command==AppCommand.NudgeLeft?-_timeline.Grid:_timeline.Grid))));else if(command==AppCommand.LengthLeft||command==AppCommand.LengthRight)changes.Add(new ResizeRegionCommand(t.Id,r.Id,r.LengthBeats,Math.Max(.25,r.LengthBeats+(command==AppCommand.LengthLeft?-_timeline.Grid:_timeline.Grid))));}if(changes.Count>0){_history.Execute(_project,new CompositeCommand("Edit regions",changes));RefreshState();}return true;}
   if(command==AppCommand.CreateTrackStack){ShowStackMenu();return true;}if(command==AppCommand.CreateFolderStack||command==AppCommand.CreateSummingStack){CreateTrackStack(command==AppCommand.CreateSummingStack);return true;}
   if(command==AppCommand.JoinRegions){JoinSelectedRegions();return true;}
   if(command==AppCommand.InvertSelection){_timeline.InvertRegionSelection();return true;}if(command==AppCommand.ZoomFitSelection){_timeline.FitSelection();return true;}if(command==AppCommand.ToolMenu){var tools=new ContextMenuStrip();foreach(string name in new[]{"Pointer","Pencil","Scissors"}){string tool=name;tools.Items.Add(UiText.Translate(tool),null,delegate{_timeline.SetTool(tool);});}tools.Show(MousePosition);return true;}if(command==AppCommand.SelectAll){_timeline.SelectAllRegions();return true;}if(command==AppCommand.DeselectAll){_timeline.ClearRegionSelection();_selectedRegionId=null;RefreshState();return true;}
   if(command==AppCommand.Copy||command==AppCommand.Cut){CopyRegions(command==AppCommand.Cut);return true;}if(command==AppCommand.Paste){PasteRegions();return true;}if(command==AppCommand.DeleteRegion&&_timeline.SelectedRegions.Count>1){DeleteRegions();return true;}
   if(command==AppCommand.ShowGlobalTracks){_globalTracks.Height=_globalTracks.Height<20?(int)(116*DisplayScale.For(this)):8;_globalTracks.Invalidate();return true;}if(command==AppCommand.MitLicences){ShowMitLicences();return true;}if(command==AppCommand.ImportVideo){using(var d=new OpenFileDialog{Filter="Movies|*.mp4;*.mov;*.m4v;*.avi;*.mkv"})if(d.ShowDialog(this)==DialogResult.OK)ImportMovie(d.FileName);return true;}return false;
  }
  private void ShowStackMenu(){var menu=new ContextMenuStrip();menu.Items.Add(UiText.Translate("Create Folder Stack"),null,delegate{CreateTrackStack(false);});menu.Items.Add(UiText.Translate("Create Mix Stack"),null,delegate{CreateTrackStack(true);});menu.Show(MousePosition);}
  private void CreateTrackStack(bool summing){try{_engine.CapturePluginStates();Guid parent;var after=TrackStackOperations.Create(_project,_timeline.SelectedTracks,summing,out parent);_history.Execute(_project,new SetProjectContentCommand("Create track stack",_project,after));Select(parent,null);}catch(Exception ex){ShowError("Could not create track stack",ex);}}
  private void ToggleTrackStack(Guid id){var state=_project.Studio.Copy();var stack=state.Stacks.Find(x=>x.ParentId==id);if(stack==null)return;stack.Collapsed=!stack.Collapsed;CommitStudio("Toggle track stack",state);}
  private void JoinSelectedRegions(){try{var ids=new HashSet<Guid>(_timeline.SelectedRegions);if(ids.Count<2){_statusLabel.Text=UiText.Translate("Select at least two regions on the same track.");return;}var owners=_project.Tracks.Where(t=>t.Regions.Any(r=>ids.Contains(r.Id))).ToList();if(owners.Count!=1||owners[0].Regions.Count(r=>ids.Contains(r.Id))!=ids.Count){_statusLabel.Text=UiText.Translate("Select at least two regions on the same track.");return;}if(_project.Studio.Cells.Any(c=>ids.Contains(c.RegionId))||_project.Studio.Comps.Any(c=>c.Takes.Any(ids.Contains))){_statusLabel.Text=UiText.Translate("Regions used by Launcher or comping cannot be joined.");return;}var track=owners[0];var regions=track.Regions.Where(r=>ids.Contains(r.Id)).ToList();string path=null;if(track.Type==TrackType.Audio){string folder=String.IsNullOrEmpty(_projectPath)?Path.Combine(Path.GetDirectoryName(SettingsStore.DefaultPath),"Recordings"):Path.Combine(Path.GetDirectoryName(_projectPath),"Media");Directory.CreateDirectory(folder);path=Path.Combine(folder,"Joined-"+Guid.NewGuid().ToString("N")+".wav");}var merged=RegionMerge.Build(_project,track,regions,path,_settings.SampleRate);_engine.CapturePluginStates();var after=ProjectFactory.Clone(_project);var target=after.Tracks.Find(t=>t.Id==track.Id);target.Regions.RemoveAll(r=>ids.Contains(r.Id));target.Regions.Add(merged);_history.Execute(_project,new SetProjectContentCommand("Join regions",_project,after));Select(track.Id,merged.Id);}catch(Exception ex){ShowError("Could not join regions",ex);}}
  private void CopyRegions(bool cut){var selected=new HashSet<Guid>(_timeline.SelectedRegions);if(selected.Count==0&&_selectedRegionId.HasValue)selected.Add(_selectedRegionId.Value);_regionClipboard.Clear();foreach(var t in _project.Tracks)foreach(var r in t.Regions)if(selected.Contains(r.Id))_regionClipboard.Add(Tuple.Create(t.Id,t.Type,CopyRegionData(r,false)));if(cut)DeleteRegions();}
  private void DeleteRegions(){var selected=new HashSet<Guid>(_timeline.SelectedRegions);if(selected.Count==0&&_selectedRegionId.HasValue)selected.Add(_selectedRegionId.Value);var after=ProjectFactory.Clone(_project);foreach(var t in after.Tracks)t.Regions.RemoveAll(r=>selected.Contains(r.Id));_history.Execute(_project,new SetProjectContentCommand("Delete regions",_project,after));_selectedRegionId=null;_timeline.ClearRegionSelection();RefreshState();}
  private void PasteRegions(){if(_regionClipboard.Count==0)return;double first=_regionClipboard.Min(x=>x.Item3.StartBeat);int sourceIndex=_project.Tracks.FindIndex(t=>t.Id==_regionClipboard[0].Item1),targetIndex=SelectedTrack==null?sourceIndex:_project.Tracks.IndexOf(SelectedTrack);var commands=new List<IProjectCommand>();Guid? lastTrack=null,lastRegion=null;foreach(var item in _regionClipboard){int index=_project.Tracks.FindIndex(t=>t.Id==item.Item1)+targetIndex-sourceIndex;Track target=index>=0&&index<_project.Tracks.Count?_project.Tracks[index]:null;if(target==null||target.Type!=item.Item2)target=_project.Tracks.Find(t=>t.Id==item.Item1);if(target==null)continue;var region=CopyRegionData(item.Item3,true);region.StartBeat=Math.Max(0,_cursorBeat+region.StartBeat-first);commands.Add(new AddRegionCommand(target.Id,region,target.Regions.Count));lastTrack=target.Id;lastRegion=region.Id;}if(commands.Count>0){_history.Execute(_project,new CompositeCommand("Paste regions",commands));Select(lastTrack,lastRegion);}}
  private void ShowInstrumentMenu(Track track){if(track==null||track.Type!=TrackType.Midi)return;var menu=new ContextMenuStrip();_instrumentMenu=menu;var sampler=new ToolStripMenuItem("Sampler");foreach(var sound in BuiltinSounds.Names){string copy=sound;var item=sampler.DropDownItems.Add(UiText.Translate(sound),null,delegate{Select(track.Id,_selectedRegionId);SelectPreset(copy);});if(item is ToolStripMenuItem)((ToolStripMenuItem)item).Checked=!track.ExternalMidi&&!track.Plugins.Any(p=>p.IsInstrument)&&track.Instrument==sound;}menu.Items.Add(sampler);foreach(var format in new[]{"VST3","CLAP"}){var group=new ToolStripMenuItem(format);foreach(var descriptor in PluginCatalog.Items.Where(p=>p.Format==format&&p.Instrument).OrderBy(p=>p.Name)){var copy=descriptor;group.DropDownItems.Add(copy.Name,null,delegate{LoadPlugin(track,copy);});}if(group.DropDownItems.Count==0)group.DropDownItems.Add(UiText.Translate("Scan instruments in Plug-in Manager")).Enabled=false;menu.Items.Add(group);}menu.Items.Add(UiText.Translate("Plug-in Manager…"),null,delegate{BrowsePlugin(track);});UiText.ApplyItems(menu.Items);menu.Closed+=delegate{if(IsHandleCreated&&!IsDisposed)BeginInvoke((Action)delegate{menu.Dispose();});};menu.Show(MousePosition);}
  private void ShowMidiMonitor(){var window=new Form{Text=UiText.Translate("MIDI Input Monitor"),Size=new Size(650,320),BackColor=Color.FromArgb(34,36,40),ForeColor=Color.Gainsboro,StartPosition=FormStartPosition.CenterParent};var status=new Label{Dock=DockStyle.Top,Height=80,Padding=new Padding(16),Font=new Font("Segoe UI",10)};var list=new ListBox{Dock=DockStyle.Fill,BackColor=Color.FromArgb(26,29,33),ForeColor=Color.FromArgb(163,210,237),Font=new Font("Consolas",10)};window.Controls.Add(list);window.Controls.Add(status);long last=-1;var timer=new Timer{Interval=50};timer.Tick+=delegate{status.Text=UiText.Translate("MIDI input")+": "+(_engine.MidiInputName??UiText.Translate("None"))+Environment.NewLine+UiText.Translate("Messages")+": "+_engine.MidiMessageCount+"   ·   "+UiText.Translate("Selected instrument receives MIDI without record-enable.");if(last!=_engine.MidiMessageCount){last=_engine.MidiMessageCount;var message=_engine.LastMidiMessage;if(message!=null){list.Items.Insert(0,message.Status.ToString("X2")+"  "+message.Data1.ToString("000")+"  "+message.Data2.ToString("000"));if(list.Items.Count>256)list.Items.RemoveAt(256);}}};window.FormClosed+=delegate{timer.Stop();timer.Dispose();};window.Shown+=delegate{UiText.Apply(window);timer.Start();};window.Show(this);}
  private void ShowMitLicences(){using(var dialog=new Form{Text="MIT Licences",Size=new Size(850,680),StartPosition=FormStartPosition.CenterParent,BackColor=Color.FromArgb(34,34,36),ForeColor=Color.Gainsboro}){var text=new RichTextBox{Dock=DockStyle.Fill,ReadOnly=true,BackColor=Color.FromArgb(34,34,36),ForeColor=Color.Gainsboro,Font=new Font("Segoe UI",10),BorderStyle=BorderStyle.None,DetectUrls=true};var parts=new List<string>();string root=AppDomain.CurrentDomain.BaseDirectory;string own=Path.Combine(root,"LICENSE");if(File.Exists(own))parts.Add("SLOP STUDIO\r\n\r\n"+File.ReadAllText(own));string folder=Path.Combine(root,"licenses");if(Directory.Exists(folder))foreach(var file in Directory.GetFiles(folder,"*.txt")){string content=File.ReadAllText(file);if(content.Contains("Permission is hereby granted, free of charge"))parts.Add(Path.GetFileName(file)+"\r\n\r\n"+content);}text.Text=String.Join("\r\n\r\n────────────────────────\r\n\r\n",parts);dialog.Controls.Add(text);UiText.Apply(dialog);dialog.ShowDialog(this);}}
  private void RequestUiScale(){if(_scaleTimer!=null){_scaleTimer.Stop();_scaleTimer.Start();}else ApplyUiScale();}
 }
